SELECT id, device, started_at, country, ROW_NUMBER() OVER (PARTITION BY device ORDER BY started_at ASC, id ASC) AS row_seq, FIRST_VALUE(browser) IGNORE NULLS OVER (PARTITION BY device ORDER BY started_at ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_browser, ROW_NUMBER() OVER (PARTITION BY browser ORDER BY started_at DESC, id ASC) AS event_seq FROM sessions WHERE browser IS NULL;
